import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './Shop.css';

const Shop = () => {
    const [products, setProducts] = useState([]);
    const [cart, setCart] = useState([]);
    const [customer, setCustomer] = useState({ name: '', email: '', phone: '', address: '' });
    const [showCheckout, setShowCheckout] = useState(false);
    const [loading, setLoading] = useState(true);
    const [orderSuccess, setOrderSuccess] = useState(false);

    useEffect(() => {
        fetchProducts();
    }, []);

    const fetchProducts = async () => {
        try {
            const response = await axios.get('http://localhost:8080/api/stock/available');
            setProducts(response.data);
            setLoading(false);
        } catch (error) {
            console.error('Error fetching products:', error);
            setLoading(false);
        }
    };

    const addToCart = (product) => {
        const existing = cart.find(item => item.id === product.id);
        
        if (existing) {
            if (existing.quantity < product.stockQuantity) {
                setCart(cart.map(item =>
                    item.id === product.id
                        ? { ...item, quantity: item.quantity + 1 }
                        : item
                ));
            } else {
                alert('Not enough stock available!');
            }
        } else {
            if (product.stockQuantity > 0) {
                setCart([...cart, { ...product, quantity: 1 }]);
            } else {
                alert('Product out of stock!');
            }
        }
    };

    const removeFromCart = (productId) => {
        setCart(cart.filter(item => item.id !== productId));
    };

    const updateQuantity = (productId, newQuantity) => {
        const product = products.find(p => p.id === productId);
        
        if (newQuantity <= 0) {
            removeFromCart(productId);
        } else if (newQuantity <= product.stockQuantity) {
            setCart(cart.map(item =>
                item.id === productId
                    ? { ...item, quantity: newQuantity }
                    : item
            ));
        } else {
            alert('Not enough stock available!');
        }
    };

    const calculateTotal = () => {
        return cart.reduce((total, item) => total + (item.unitPrice * item.quantity), 0).toFixed(2);
    };

    const handleCheckout = async (e) => {
        e.preventDefault();
        
        if (cart.length === 0) {
            alert('Your cart is empty!');
            return;
        }

        const orderData = {
            customer: {
                name: customer.name,
                email: customer.email,
                phone: customer.phone,
                address: customer.address
            },
            orderDate: new Date().toISOString(),
            status: 'PENDING',
            items: cart.map(item => ({
                product: { id: item.id },
                quantity: item.quantity,
                unitPrice: item.unitPrice
            }))
        };

        try {
            const response = await axios.post('http://localhost:8080/api/orders', orderData);
            setOrderSuccess(true);
            setCart([]);
            setCustomer({ name: '', email: '', phone: '', address: '' });
            setShowCheckout(false);
            fetchProducts(); // Refresh product list
            
            setTimeout(() => {
                setOrderSuccess(false);
            }, 5000);
        } catch (error) {
            console.error('Error creating order:', error);
            alert('Failed to create order. Please try again.');
        }
    };

    if (loading) {
        return <div className="loading">Loading products...</div>;
    }

    return (
        <div className="shop-container">
            <h1>Customer Order System</h1>
            
            {orderSuccess && (
                <div className="success-message">
                    ✓ Order placed successfully! Thank you for your purchase.
                </div>
            )}

            <div className="shop-layout">
                <div className="products-section">
                    <h2>Available Products</h2>
                    <div className="product-grid">
                        {products.map(product => (
                            <div key={product.id} className="product-card">
                                <h3>{product.name}</h3>
                                <p className="description">{product.description}</p>
                                <p className="sku">SKU: {product.sku}</p>
                                <p className="price">${product.unitPrice?.toFixed(2)}</p>
                                <p className={`stock ${product.stockQuantity > 0 ? 'in-stock' : 'out-of-stock'}`}>
                                    {product.stockQuantity > 0 
                                        ? `In Stock: ${product.stockQuantity}` 
                                        : 'Out of Stock'}
                                </p>
                                <button 
                                    onClick={() => addToCart(product)}
                                    disabled={product.stockQuantity === 0}
                                    className="add-to-cart-btn"
                                >
                                    Add to Cart
                                </button>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="cart-section">
                    <h2>Shopping Cart ({cart.length})</h2>
                    
                    {cart.length === 0 ? (
                        <p className="empty-cart">Your cart is empty</p>
                    ) : (
                        <>
                            <div className="cart-items">
                                {cart.map(item => (
                                    <div key={item.id} className="cart-item">
                                        <div className="cart-item-info">
                                            <h4>{item.name}</h4>
                                            <p>${item.unitPrice?.toFixed(2)} each</p>
                                        </div>
                                        <div className="cart-item-controls">
                                            <button onClick={() => updateQuantity(item.id, item.quantity - 1)}>-</button>
                                            <span>{item.quantity}</span>
                                            <button onClick={() => updateQuantity(item.id, item.quantity + 1)}>+</button>
                                            <button onClick={() => removeFromCart(item.id)} className="remove-btn">×</button>
                                        </div>
                                        <div className="cart-item-total">
                                            ${(item.unitPrice * item.quantity).toFixed(2)}
                                        </div>
                                    </div>
                                ))}
                            </div>
                            
                            <div className="cart-total">
                                <h3>Total: ${calculateTotal()}</h3>
                            </div>

                            <button 
                                onClick={() => setShowCheckout(!showCheckout)}
                                className="checkout-btn"
                            >
                                {showCheckout ? 'Hide Checkout' : 'Proceed to Checkout'}
                            </button>

                            {showCheckout && (
                                <form onSubmit={handleCheckout} className="checkout-form">
                                    <h3>Customer Information</h3>
                                    <input
                                        type="text"
                                        placeholder="Full Name *"
                                        value={customer.name}
                                        onChange={(e) => setCustomer({ ...customer, name: e.target.value })}
                                        required
                                    />
                                    <input
                                        type="email"
                                        placeholder="Email *"
                                        value={customer.email}
                                        onChange={(e) => setCustomer({ ...customer, email: e.target.value })}
                                        required
                                    />
                                    <input
                                        type="tel"
                                        placeholder="Phone"
                                        value={customer.phone}
                                        onChange={(e) => setCustomer({ ...customer, phone: e.target.value })}
                                    />
                                    <textarea
                                        placeholder="Shipping Address *"
                                        value={customer.address}
                                        onChange={(e) => setCustomer({ ...customer, address: e.target.value })}
                                        required
                                        rows="3"
                                    />
                                    <button type="submit" className="place-order-btn">
                                        Place Order
                                    </button>
                                </form>
                            )}
                        </>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Shop;
